/**
 * Note: The returned array must be malloced, assume caller calls free().
 */
int* twoSum(int* nums, int numsSize, int target, int* returnSize) {
    *returnSize = 2;
    int* res = (int*)malloc(2 * sizeof(int));
    #define HASH_SIZE 32768
    typedef struct Node {
        int key;
        int val;
        struct Node* next;
    } Node;
    Node* table[HASH_SIZE] = {0};
    for (int i = 0; i < numsSize; i++) {
        int comp = target - nums[i];
        unsigned int h = ((unsigned int)comp) % HASH_SIZE;
        Node* curr = table[h];
        while (curr) {
            if (curr->key == comp) {
                res[0] = curr->val;
                res[1] = i;
                return res;
            }
            curr = curr->next;
        }
        unsigned int h2 = ((unsigned int)nums[i]) % HASH_SIZE;
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->key = nums[i];
        newNode->val = i;
        newNode->next = table[h2];
        table[h2] = newNode;
    }
    return res;
}

