public class Main {
    static int[] parseIntArray(String s) {
        s = s.trim();
        if (s.startsWith("[")) s = s.substring(1);
        if (s.endsWith("]")) s = s.substring(0, s.length() - 1);
        s = s.trim();
        if (s.isEmpty()) return new int[0];
        String[] parts = s.split(",");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; i++) arr[i] = Integer.parseInt(parts[i].trim());
        return arr;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        int firstBracket = line.indexOf('[');
        int midBracket = line.indexOf(']', firstBracket);
        String arrStr = line.substring(firstBracket + 1, midBracket + 1);
        int[] nums = parseIntArray(arrStr);
        int commaAfter = line.indexOf(',', midBracket);
        int lastBracket = line.lastIndexOf(']');
        int target = Integer.parseInt(line.substring(commaAfter + 1, lastBracket).trim());

        int[] res = new Solution().twoSum(nums, target);
        System.out.println("[" + res[0] + "," + res[1] + "]");
    }
}

